const escape = text => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
let RULES = null;
function rules() {
  // Setting labels appear at the start of the structured settings' own messages ("Visible rows: use an integer...").
  const labels = SETTINGS.filter(spec => SETTING_TEXT[`${spec.scope}:${spec.path}`]).map(spec => [`${spec.label}:`, `${SETTING_TEXT[`${spec.scope}:${spec.path}`][0]}:`]);
  return [...TABLE, ...labels].map(([pattern, replacement]) => {
    const literal = pattern.replaceAll('{}', '');
    // {} stops at the next known text; a {} that ends the pattern is one word (a player name or a screen id).
    const source = pattern.split('{}').map(escape).join('(.+?)').replace(/\(\.\+\?\)$/, '(\\S+)');
    return { literal: literal.length, regex: new RegExp(source, 'g'), replacement };
  }).sort((a, b) => b.literal - a.literal);
}

/** {@code message} in Spanish: every known English phrase replaced; Spanish text and unknown words stay as they are. */
export function es(message) {
  let text = String(message ?? '');
  if (!/[A-Za-z]/.test(text)) return text;
  RULES ??= rules();
  for (const rule of RULES) if (rule.regex.test(text)) { rule.regex.lastIndex = 0; text = text.replace(rule.regex, rule.replacement); }
  return text;
}
export const TRANSLATIONS = TABLE.length;

